// Перенос anki_conf/.../CoursesPanel/route/route-lemmas.ts как есть (план B8a).
// =============================================================
// СЛОВА СТРОКИ для пословных событий маршрута (clipboard_copy, line_translated).
//
// ⚠️ ЧИСТЫЙ МОДУЛЬ БЕЗ ИМПОРТОВ. Его тянут попапы и плеер; модуль эмиттера тянет стор и
// сеть, и тесты компонентов его подменяют целиком — помощник, живущий там, исчезал бы
// вместе с подменой.
// ⚠️ Деление — как у clip_replayed (route-clip-events.ts): латиница + апостроф/дефис.
// Русский текст даёт пустой список — лексемы обязаны быть английскими поверхностными
// формами, демон лемматизирует сам.
// =============================================================

/** wordsOf — английские слова строки: нижний регистр, без однобуквенных, уникально, в порядке появления.
 *  Токены без единой буквы («--», «''») — не слова: демону не уходят. */
export function wordsOf(text: string): string[] {
  const out: string[] = [];
  for (const w of (text || '').toLowerCase().split(/[^a-zà-ÿ'-]+/i)) {
    if (w.length > 1 && /[a-zà-ÿ]/i.test(w) && !out.includes(w)) out.push(w);
  }
  return out;
}

/**
 * l1CopyLemmas — Ctrl+C в РУССКОЙ строке. Русские слова демону не нужны: событие несёт
 * слова ТЕКУЩЕЙ английской строки (её человек и не понял, раз копирует перевод).
 * Пустое выделение или нет английской строки — ничего.
 */
export function l1CopyLemmas(selection: string, enLine: string | null | undefined): string[] {
  if (!(selection || '').trim() || !enLine) return [];
  return wordsOf(enLine);
}
